NIVEAUX = ["A1"]*6+["A2"]*7+["B1"]*7+["B2"]*8+["C1"]*7+["C2"]*5
assert len(CO)==len(CE)==40
for examen, nombre in (("tef",40),("tcf",39)):
 sections={}
 for section,rows in (("co",CO),("ce",CE)):
  items=[]
  for i,row in enumerate(rows[:nombre]):
   texte,question,*options=row
   rotation=i%4
   choix=options[-rotation:]+options[:-rotation] if rotation else options
   items.append({"id":f"{section}{i+1:02d}","niveau":NIVEAUX[i],"texte":texte,"question":question,"choix":choix,"correct":rotation,"audio":f"simulados/audio/co{i+1:02d}.mp3" if section=="co" else None})
  sections[section]=items
 (ROOT/'data/simulados'/f'{examen}.json').write_text(json.dumps({"version":1,"original":True,"partage_editorial":True,"sections":sections},ensure_ascii=False,indent=2))
print("80 itens originais; bancos completos TEF 40+40 e TCF 39+39, com itens compartilhados.")
